import{z as o,x as s,o as a,c as l,q as B,j as A,D as e,d as n,s as i,S as t}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"最低工资：两代文献","description":"","frontmatter":{"title":"最低工资：两代文献","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/minimum-wage-debates.md","filePath":"econ/minimum-wage-debates.md","lastUpdated":1791413859000}'),d={name:"econ/minimum-wage-debates.md"};function m(p,E,c,C,h,u){const r=s("Mermaid");return a(),l("div",null,[E[2]||(E[2]=B('<h1 id="最低工资-两代文献" tabindex="-1">最低工资：两代文献 <a class="header-anchor" href="#最低工资-两代文献" aria-label="Permalink to &quot;最低工资：两代文献&quot;">​</a></h1><div class="epigraph"><p>一代文献从竞争模型推出失业，另一代文献去快餐店数人头；分歧不在价值偏好，而在劳动供给曲线到底有多平。</p><footer>—— 据 Stigler, The Economics of Minimum Wage Legislation, AER 1946；Card and Krueger, AER 1994 整理</footer></div><p><a href="/econ/monopsony-wages">上一课</a>给了本课的地基：摩擦使厂商面对向上的劳动供给，工资压在 MRP 之下，缺口由弹性决定。于是法定下限的效应不再是竞争模型一句话能钉死的。本课是劳动经济学课程的收束：把两代最低工资文献当作这门课的测验题——它同时用上供给需求（MRP 与弹性）、买方垄断、制度与识别。计数工具在<a href="/econ/difference-in-differences">双重差分</a>已经拆过，Card–Krueger 是那里的教具；本课直接进文献的分野与解释。劳动经济学到此收束：树序下一课转入产业组织的首课<a href="/econ/scp-neio">SCP 与新实证 IO</a>，从要素市场回到产品市场结构。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>第一代文献（1946–1992）从竞争模型出发：下限高于均衡工资，需求量收缩、供给量扩张，青少年与非熟练工首当其冲。Stigler 1946 给出经典陈述；时间序列估计把青少年就业对最低工资的弹性收在 \\(-0.1\\) 到 \\(-0.3\\) 之间。第二代文献从 Card–Krueger 1994 开始：新泽西上调最低工资，用隔壁宾州的快餐店做对照，差中差发现就业没有下降，点估计甚至为正。Neumark–Wascher 随后用工资记录数据、青少年子样本与更长的面板给出负效应的反证，两线缠斗至今。缺口不是站队，而是：若竞争模型的预测如此干脆，为什么数据里弹性这么小。</p>',5)),(a(),A(t,null,{default:e(()=>[i(r,{id:"mermaid-13",class:"mermaid",graph:"flowchart%20TD%0A%20%20FLOOR%5B%22%E6%B3%95%E5%AE%9A%E4%B8%8B%E9%99%90%20w_min%22%5D%20--%3E%20C1%5B%22%E7%AB%9E%E4%BA%89%E6%A8%A1%E5%9E%8B%EF%BC%9A%E4%B8%8B%E9%99%90%E8%B6%8A%E7%BA%BF%20%E2%86%92%20%E5%B0%B1%E4%B8%9A%E2%86%93%22%5D%0A%20%20FLOOR%20--%3E%20C2%5B%22%E4%B9%B0%E6%96%B9%E5%9E%84%E6%96%AD%EF%BC%9Aw%20%E4%BD%8E%E4%BA%8E%20MRP%20%E5%8C%BA%E9%97%B4%20%E2%86%92%20%E6%8A%AC%E5%90%91%20MRP%22%5D%0A%20%20C1%20--%3E%20DATA%5B%22%E5%AE%9E%E8%AF%81%EF%BC%9A%E5%BC%B9%E6%80%A7%E8%BF%91%E4%BC%BC%E9%9B%B6%E6%88%96%E5%B0%8F%E8%B4%9F%22%5D%0A%20%20C2%20--%3E%20DATA%0A%20%20DATA%20--%3E%20MARG%5B%22%E8%B0%83%E6%95%B4%E8%BE%B9%E9%99%85%EF%BC%9A%E4%BB%B7%E6%A0%BC%E3%80%81%E5%B7%A5%E6%97%B6%E3%80%81%E8%BF%9B%E5%85%A5%E9%80%80%E5%87%BA%22%5D%0A%20%20MARG%20--%3E%20NEXT%5B%22%E5%A4%96%E6%8E%A8%E8%AD%A6%E6%88%92%EF%BC%9A%E5%A4%A7%E4%B8%8A%E8%B0%83%E3%80%81%E9%95%BF%E6%9C%9F%E3%80%81%E7%A9%BA%E9%97%B4%E5%BC%82%E8%B4%A8%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[n(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B('<p><span class="marginnote">接上一课的算术：若 \\(w = 0.7\\,\\mathrm{MRP}\\)，下限抬升一成仍在 MRP 之下，不必然减员；一旦下限越过 MRP，竞争逻辑立刻回来。买方垄断不是否认就业效应，是给「多小的下限才安全」定了位置。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>第二代文献的推进主要在设计。Card–Krueger 的两州两组之后：Dube–Lester–Reich 2010 用相邻县做对照，把区域趋势差洗掉；Cengiz–Dube–Lindner–Zipperer 2019 收集一百多次州级上调，把「新下限之上窗口里消失的工作」当作就业变化的读数，发现受影响岗位几乎没有净损失，工资确实涨了。正面证据之外，Neumark–Wascher 2007 的综述仍报出多数研究偏负，并指出对照组选择（全国青少年基线的预趋势问题）是第二代的高发伤。两代读同一份世界，分歧来自对照的构造，而不是道德立场。</p><p><span class="marginnote">「对照」就是给处理组找一个平行世界的替身：新泽西涨了，宾州没涨，宾州快餐店的就业变化就当作「新泽西若不涨」的反事实。差中差洗掉的是两州共有的时间趋势；若宾州自己的走势和新泽西本就不同，差出来的数字里混的就是趋势差而非政策效应。Dube 等人改用一河之隔的相邻县，正是为了让替身更逼真——两县几乎共用同一个劳动力市场。</span></p><p>错在哪：把 1994 年的一次快餐调查当成普适常数。外推有两条红线：上调幅度大到越过 MRP（大上调与翻倍不是小调的外延）；时间维度拉长（短期工资单没动，不等于资本替代与自动化不发生——那是<a href="/econ/directed-technical-change">有偏技术进步</a>的通道）。空间异质性同样要紧：低工资地区的就业反应大于高工资都市，用全国平均弹性做政策评估会算错方向。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么小弹性可能成立，机制清单是这门课的复习：其一，买方垄断（上一课）：压价区间里抬工资沿 MRP 补员，就业不减。其二，<a href="/econ/efficiency-wage">效率工资</a>：工资本可以钉在出清之上，下限若落在厂商自愿区间内，只是换了一种抬法——那里已经警告过识别必须声明，本课沿用。其三，调整边际的再分配：就业是存量，工资单之外还有价格（Harasztosi–Lindner 2019 的大上调里相当部分由涨价吸收）、工时、佣金、进入退出——盯住「受影响工人有没有被裁」会漏掉全边际。其四，失业率反应温和：下限动的是工资分布下截，流入流出在<a href="/econ/unemployment-stock-flow">存量-流量</a>的账上大部分抵消。</p>',7)),(a(),A(t,null,{default:e(()=>[i(r,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20LR%0A%20%20HIKE%5B%22%E6%9C%80%E4%BD%8E%E5%B7%A5%E8%B5%84%E4%B8%8A%E8%B0%83%22%5D%20--%3E%20M1%5B%22%E4%B9%B0%E6%96%B9%E5%9E%84%E6%96%AD%EF%BC%9A%E5%8E%8B%E4%BB%B7%E5%8C%BA%E9%97%B4%E5%86%85%E6%8A%AC%E8%96%AA%EF%BC%8C%E6%B2%BF%20MRP%20%E8%A1%A5%E5%91%98%22%5D%0A%20%20HIKE%20--%3E%20M2%5B%22%E6%95%88%E7%8E%87%E5%B7%A5%E8%B5%84%EF%BC%9A%E4%B8%8B%E9%99%90%E8%90%BD%E5%9C%A8%E8%87%AA%E6%84%BF%E5%87%BA%E6%B8%85%E5%8C%BA%E9%97%B4%E5%86%85%22%5D%0A%20%20HIKE%20--%3E%20M3%5B%22%E8%B0%83%E6%95%B4%E8%BE%B9%E9%99%85%EF%BC%9A%E6%B6%A8%E4%BB%B7%E3%80%81%E5%87%8F%E5%B7%A5%E6%97%B6%E3%80%81%E4%BD%A3%E9%87%91%E3%80%81%E8%BF%9B%E5%85%A5%E9%80%80%E5%87%BA%22%5D%0A%20%20HIKE%20--%3E%20M4%5B%22%E5%AD%98%E9%87%8F-%E6%B5%81%E9%87%8F%EF%BC%9A%E6%B5%81%E5%85%A5%E6%B5%81%E5%87%BA%E5%A4%A7%E9%83%A8%E5%88%86%E6%8A%B5%E6%B6%88%22%5D%0A%20%20M1%20--%3E%20OBS%5B%22%E8%B4%A6%E9%9D%A2%E4%B8%8A%E5%B0%B1%E4%B8%9A%E5%87%A0%E4%B9%8E%E4%B8%8D%E5%8A%A8%22%5D%0A%20%20M2%20--%3E%20OBS%0A%20%20M3%20--%3E%20OBS%0A%20%20M4%20--%3E%20OBS%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[n(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=B('<p><span class="marginnote">「调整边际」指厂商消化工资上涨的所有旁路：涨价转给顾客、缩短工时、下调佣金或福利、放缓开店、用自动化顶替。就业只是其中一个存量读数——初学者容易只盯「有没有人被裁」，实际上成本完全可以在工资单之外吸收，这正是大上调研究里相当部分成本由涨价吸收的原因。</span></p><p>作为收束，这道题的答案是：两代文献都对，各自在自己的模型区间里。哪一代适用于哪一次上调，要看 markdown 多深（上一课）、调整边际多少（本课）、对照多近（DiD 课）。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不做各国的法定参数比较，不写生活工资与贫困率的福利核算——最低工资不是精准的贫困工具，受益者不少不在低收入家庭。调查数据与工资记录的口径之争（Card–Krueger 的电话调查对 Neumark–Wascher 的记录）是测量课的案例，这里只记结论对口径敏感。负效应研究并不错，正效应研究也未必对：识别的战场在对照组，永远在。</p><p><span class="marginnote">弹性 \\(-0.1\\) 怎么读：最低工资上调 10%，青少年就业量大约只降 1%。常见误区是把它当成「工资涨多少、失业率就涨多少个百分点」——它度量的是就业量对工资的百分比响应，分母与失业率完全不同，直接搬数字会差一个量级。</span>后课默认：读到任何工资下限的证据，先问模型区间、调整边际与对照构造三件事；劳动经济学课程到此收束。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>第一代：竞争模型的时间序列；第二代：Card–Krueger 之后的自然实验。</li><li>小弹性不推翻竞争模型：买方垄断、效率工资与调整边际都能接住它。</li><li>外推有红线：越线的大上调、长期弹性、空间异质。</li><li>两代分歧在对照组的构造，不在价值立场。</li><li>劳动经济学收束于此；树序下一课是产业组织首课 SCP 与新实证 IO。</li><li>出处：Stigler 1946；Card and Krueger, AER 1994；Neumark–Wascher 系列；Cengiz et al., QJE 2019；Manning 2003。</li></ul>',7))])}const f=o(d,[["render",m]]);export{D as __pageData,f as default};
